            if routes and route_load(routes[-1]) + di <= capacity:
                routes[-1].append(i)
                placed = True
            if not placed:
                routes.append([i])
    else:
        unassigned.sort(key=lambda i: (-demand(i), -dist(depot, i), i))
        while unassigned:
            r = []
            load = 0
            first = None
            feas = [i for i in unassigned if demand(i) <= capacity]
            if feas:
                first = max(feas, key=lambda i: (dist(depot, i), demand(i), -i))
            else:
                first = unassigned[0]
            r.append(first)
            load += demand(first)
            unassigned.remove(first)
            cur = first
            while True:
                best = None
                best_key = None
                for i in unassigned:
                    di = demand(i)
                    if load + di > capacity:
                        continue
                    key = (dist(cur, i), -di, i)
                    if best_key is None or key < best_key:
                        best_key = key
                        best = i
                if best is None:
                    break
                r.append(best)
                load += demand(best)
                unassigned.remove(best)
                cur = best
            routes.append(r)

    assigned = set()
    for r in routes:
        for c in r:
            assigned.add(c)
    for c in cust_ids:
        if c not in assigned:
            best = None
            best_r = None
            best_p = None
            for ri, r in enumerate(routes):
                if route_load(r) + demand(c) > capacity:
                    continue
                for p in range(len(r) + 1):
                    a = depot if p == 0 else r[p - 1]
                    b = depot if p == len(r) else r[p]
                    delta = dist(a, c) + dist(c, b) - dist(a, b)
                    if best is None or delta < best:
                        best = delta
                        best_r = ri
                        best_p = p
            if best_r is None:
                routes.append([c])
            else:
                routes[best_r].insert(best_p, c)

    def two_opt(r):
        n = len(r)
        if n < 4:
            return r[:]
        best = r[:]
        improved = True
        while improved:
            improved = False
            for i in range(n - 2):
                for j in range(i + 2, n):
                    if i == 0 and j == n - 1:
                        continue
                    cand = best[:i + 1] + best[i + 1:j + 1][::-1] + best[j + 1:]
                    if route_cost(cand) + 1e-12 < route_cost(best):
                        best = cand
                        improved = True
                        break
                if improved:
                    break
        return best

    routes = [two_opt(r) for r in routes if r]
    changed = True
    while changed:
        changed = False
        for a in range(len(routes)):
            ra = routes[a]
            for i, c in enumerate(ra):
                dc = demand(c)
                for b in range(len(routes)):
                    if a == b:
                        continue
                    rb = routes[b]
                    if route_load(rb) + dc > capacity:
                        continue
                    for p in range(len(rb) + 1):
                        pa = depot if i == 0 else ra[i - 1]
                        na = depot if i == len(ra) - 1 else ra[i + 1]
                        pb = depot if p == 0 else rb[p - 1]
                        nb = depot if p == len(rb) else rb[p]
                        delta = (dist(pa, na) - dist(pa, c) - dist(c, na)) + (dist(pb, c) + dist(c, nb) - dist(pb, nb))
                        if delta < -1e-12:
                            new_ra = ra[:i] + ra[i + 1:]
                            new_rb = rb[:p] + [c] + rb[p:]
                            routes[a] = new_ra
                            routes[b] = two_opt(new_rb)
                            if not routes[a]:
                                routes.pop(a)
                            changed = True
                            break
                    if changed:
                        break
                if changed:
                    break
            if changed:
                break
        if changed:
            continue
        for a in range(len(routes)):
            ra = routes[a]
            for b in range(a + 1, len(routes)):
                rb = routes[b]
                la = route_load(ra)
                lb = route_load(rb)
                for i, ca in enumerate(ra):
                    da = demand(ca)
                    for j, cb in enumerate(rb):
                        db = demand(cb)
                        if la - da + db > capacity or lb - db + da > capacity:
                            continue
                        a1 = depot if i == 0 else ra[i - 1]
                        a2 = depot if i == len(ra) - 1 else ra[i + 1]
                        b1 = depot if j == 0 else rb[j - 1]
                        b2 = depot if j == len(rb) - 1 else rb[j + 1]
                        old = dist(a1, ca) + dist(ca, a2) + dist(b1, cb) + dist(cb, b2)
                        new = dist(a1, cb) + dist(cb, a2) + dist(b1, ca) + dist(ca, b2)
                        if new + 1e-12 < old:
                            ra2 = ra[:]
                            rb2 = rb[:]
                            ra2[i], rb2[j] = rb2[j], ra2[i]
                            routes[a] = two_opt(ra2)
                            routes[b] = two_opt(rb2)
                            changed = True
                            break
                    if changed:
                        break
                if changed:
                    break
            if changed:
                break

    seen = set()
    final = []
    for r in routes:
        rr = [c for c in r if c != depot and c not in seen]
        for c in rr:
            seen.add(c)
        if rr:
            final.append(rr)
    for c in cust_ids:
        if c not in seen:
            final.append([c])
    return final
